save_diagrams()
for p in (ROOT/'src/lib/technical-education/lessons').glob('*.json'):
 if p.name.startswith(('M16','M17','M18')):
  p.write_text(re.sub('\u2066([^\u2069]*)\u2069',lambda m:'\u2066'+m[1].replace(' ','\u00a0')+'\u2069',p.read_text()))

# Separate Arabic words and digits for legible display and clear speech.
def spaced(v):
 if isinstance(v,str):
  v=re.sub(r'(?<=[\u0600-\u06ff])(?=\d)', ' ', v)
  return re.sub(r'(?<=\d)(?=[\u0600-\u06ff])', ' ', v)
 if isinstance(v,list):return [spaced(x) for x in v]
 if isinstance(v,dict):return {k:spaced(x) for k,x in v.items()}
 return v
for p in (ROOT/'src/lib/technical-education/lessons').glob('*.json'):
 if p.name.startswith(('M16','M17','M18')):p.write_text(json.dumps(spaced(json.loads(p.read_text())),ensure_ascii=False,indent=2)+'\n')
